DELIMITER $$
CREATE PROCEDURE sp_collect_fee(IN p_student INT UNSIGNED,IN p_structure INT UNSIGNED,IN p_method VARCHAR(10))
BEGIN DECLARE v_amount DECIMAL(10,2); DECLARE v_rate DECIMAL(5,2); DECLARE v_due DATE; DECLARE v_paid DATE; DECLARE v_late DECIMAL(10,2); DECLARE v_payment INT UNSIGNED; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; START TRANSACTION; SELECT amount,late_fee_rate,due_date INTO v_amount,v_rate,v_due FROM fee_structure WHERE fee_structure_id=p_structure FOR UPDATE; IF v_amount IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Fee structure not found'; END IF; SET v_paid=CURDATE(); SET v_late=fn_late_fee(v_amount,v_rate,v_due,v_paid); INSERT INTO fee_payment(student_id,fee_structure_id,base_amount,late_fee,total_amount,payment_method) VALUES(p_student,p_structure,v_amount,v_late,v_amount+v_late,p_method); SET v_payment=LAST_INSERT_ID(); INSERT INTO receipt(fee_payment_id,receipt_no) VALUES(v_payment,CONCAT('R-',DATE_FORMAT(NOW(),'%Y%m%d'),'-',LPAD(v_payment,6,'0'))); COMMIT; SELECT v_payment fee_payment_id; END$$
CREATE PROCEDURE sp_allocate_hostel(IN p_room INT UNSIGNED,IN p_student INT UNSIGNED)
BEGIN DECLARE v_capacity INT; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; START TRANSACTION; SELECT capacity INTO v_capacity FROM hostel_room WHERE hostel_room_id=p_room FOR UPDATE; IF v_capacity IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Room not found'; END IF; IF EXISTS(SELECT 1 FROM hostel_allocation WHERE student_id=p_student AND status='ACTIVE') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Student already has an active room'; END IF; IF fn_room_vacancy(p_room)<=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Room capacity reached'; END IF; INSERT INTO hostel_allocation(hostel_room_id,student_id,allocated_on) VALUES(p_room,p_student,CURDATE()); COMMIT; SELECT LAST_INSERT_ID() hostel_allocation_id; END$$
CREATE PROCEDURE sp_end_hostel_allocation(IN p_allocation INT UNSIGNED)
BEGIN UPDATE hostel_allocation SET status='ENDED' WHERE hostel_allocation_id=p_allocation AND status='ACTIVE'; IF ROW_COUNT()=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Active allocation not found'; END IF; END$$
DELIMITER ;
